#!/usr/bin/env python3
"""Deterministic static PrizeLens build. No network calls and no runtime dependencies."""
import csv, html, json, re
from collections import Counter
from datetime import date
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
AUDIT = '2026-11-02'
CATS = [
    ('tech', 'Tech & data', 'Hackathons, machine learning and research prizes.', '⌘'),
    ('creative', 'Creative awards', 'Photography, writing and design; check authorship rules.', '✎'),
    ('sports', 'Sports & fantasy', 'Season games and picks; residency and automation rules matter.', '◈'),
    ('forecasting', 'Forecasting', 'Probability and prediction tournaments, not wagering.', '◌'),
    ('skill', 'Skill tournaments', 'Game tournaments; separate free entry from practical costs.', '◇'),
    ('market', 'Market simulations', 'Demo trading and simulated investing; check payout form.', '↗'),
    ('trivia', 'Trivia', 'Quiz formats; distinguish cash from points and gift cards.', '?'),
    ('pools', 'Pool tools', 'Tools for running a pool are not necessarily funded prizes.', '▦'),
    ('directory', 'Directories', 'Discovery sources, not individual cash-prize offers.', '≡'),
]
CAT = dict((x[0], x[1]) for x in CATS)
AGENT = {'explicit':'Explicit agent path','conditional':'Conditional tool use','restricted':'Human-origin / team limits','prohibited':'Automated entry prohibited','unclear':'AI mentioned; agent use unclear','unreviewed':'Not reviewed'}
WINDOW = {'open':'Published window open','closing':'Closes on audit date','conditional':'Prerequisite required','rolling':'Rolling / dated observation','seasonal':'Season ended / watch next','unknown':'Not confirmed'}
inv = json.loads((ROOT/'data/inventory.json').read_text())
events = json.loads((ROOT/'research/events.json').read_text())
link_path = ROOT/'research/link-audit.json'
links = json.loads(link_path.read_text()) if link_path.exists() else None
link_by_url = {r['url']: r for r in links['results']} if links else {}
rows = inv['rows'] + events['records']
for r in rows:
    r.setdefault('fields', {}); r.setdefault('flags', []); r.setdefault('evidence', [])
    r.setdefault('window', 'unknown'); r.setdefault('agent_policy', 'unreviewed')
    r.setdefault('shortlist', False); r.setdefault('top_cash_usd', None); r.setdefault('pool_usd', None)
    r['category_name'] = CAT[r['category']]
    r['status'] = 'event-reviewed' if r['kind'] == 'event' else 'needs-review'
    r['search'] = ' '.join([r['name'], r['category_name'], r['id'], *r['flags'], *r.get('fields', {}).values()]).lower()
    if not r.get('official_url'):
        r['flags'].append('No official operator source confirmed. The source cell is blank; the inherited reference is provenance only.')
    if links and r.get('official_url') in link_by_url:
        result = link_by_url[r['official_url']]
        if result['classification'] not in ('reachable', 'redirected'):
            r['flags'].append(f'Official source reachability: {result["classification"]} (HTTP {result.get("status") or "no response"}). This is not proof of permanent breakage or contest validity.')
rows_by_id = {r['id']: r for r in rows}
assert len(rows_by_id) == len(rows)
short = [r for r in rows if r['shortlist']]
featured_ids = ['event-kiroween','event-ugreen','event-codegeist','event-paypal','event-nfl-bdb','event-sony-series']
featured = [rows_by_id[i] for i in featured_ids]
counts = {'total':len(rows),'inherited':len(inv['rows']),'events':len(events['records']),'shortlist':len(short),'missing_source':sum(not r.get('official_url') for r in rows),'categories':len(CATS),'evidence':sum(len(r['evidence']) for r in rows)}
(ROOT/'data/catalog.json').write_text(json.dumps({'audit_date':AUDIT,'counts':counts,'rows':rows},ensure_ascii=False,indent=2)+'\n')
with (ROOT/'data/catalog.csv').open('w',newline='',encoding='utf-8') as f:
    writer=csv.writer(f);writer.writerow(['id','name','category','record_type','status','official_source','free_entry','cash_prize','deadline','eligibility','agent_policy','requirements','payout','flags','checked'])
    for r in rows:
        writer.writerow([r['id'],r['name'],r['category_name'],r['kind'],r['status'],r.get('official_url') or '',*[r['fields'].get(k,'') for k in ['free','prize','deadline','eligibility']],AGENT[r['agent_policy']],r['fields'].get('requirements',''),r['fields'].get('payout',''),' | '.join(r['flags']),r.get('checked','')])

def e(v): return html.escape(str(v if v is not None else ''), quote=True)
def ext(url,label,cls='source-link'):
    return f'<a class="{cls}" href="{e(url)}" target="_blank" rel="noopener noreferrer">{e(label)}<span aria-hidden="true"> ↗</span></a>' if url else '<span class="unknown">Unverified</span>'
def blank(v):
    return e(v) if v else '<span class="blank" aria-label="Not confirmed">—</span>'
def badge(r):
    if r['kind']=='inherited': return '<span class="badge amber">Needs review</span>'
    if r['shortlist']: return '<span class="badge green">Free + cash evidence</span>'
    return '<span class="badge blue">Partial evidence</span>'
def money(v): return f'${v:,.0f}' if v is not None else ''

def table(items, table_id='catalog', compact=False):
    head = ''.join(f'<th scope="col">{h}</th>' for h in ['Competition','Free entry','Cash prize','Deadline','Agent / AI rule','Official source'])
    body=[]
    for r in items:
        f=r['fields']; url=r.get('official_url')
        source=ext(url,'Rules / official page') if url else '<span class="blank" aria-label="No confirmed official source">—</span>'
        evlink=f'<a class="evidence-link" href="sources.html#{e(r["id"])}">Evidence & review</a>' if r['kind']=='event' else f'<a class="evidence-link" href="flagged.html#flag-{e(r["id"])}">Review notes</a>'
        provenance=f'<a class="provenance" href="{e(r["provenance_url"])}" target="_blank" rel="noopener noreferrer">Inherited reference ↗</a>' if r['kind']=='inherited' else ''
        body.append(f'''<tr id="{e(r['id'])}" data-name="{e(r['name'].lower())}" data-category="{e(r['category'])}" data-status="{e(r['status'])}" data-agent="{e(r['agent_policy'])}" data-shortlist="{str(r['shortlist']).lower()}" data-deadline="{e(f.get('deadline',''))}" data-prize="{r['top_cash_usd'] or -1}" data-search="{e(r['search'])}">
<td data-label="Competition"><div class="entry-top"><span class="entry-name">{e(r['name'])}</span><button class="save-button" type="button" data-save="{e(r['id'])}" aria-label="Save {e(r['name'])}" aria-pressed="false" hidden>☆</button></div><div class="entry-meta">{badge(r)}<span class="category-label">{e(r['category_name'])}</span></div><div class="entry-links">{evlink}{provenance}</div></td>
<td data-label="Free entry">{blank(f.get('free'))}</td><td data-label="Cash prize">{blank(f.get('prize'))}</td><td data-label="Deadline">{blank(f.get('deadline'))}<span class="cell-note">{e(WINDOW[r['window']]) if r['kind']=='event' else ''}</span></td><td data-label="Agent / AI rule"><span class="agent-label {e(r['agent_policy'])}">{e(AGENT[r['agent_policy']])}</span><span class="cell-note">{blank(f.get('agent'))}</span></td><td data-label="Official source">{source}</td></tr>''')
    return f'''<div class="table-tools" data-controls="{table_id}"><div class="search-wrap"><label for="{table_id}-search">Search competitions</label><input id="{table_id}-search" type="search" placeholder="Name, category or requirement…" autocomplete="off"></div><div class="filter-row"><label>Category<select id="{table_id}-category"><option value="">All categories</option>{''.join(f'<option value="{k}">{e(v)}</option>' for k,v,_,_ in CATS)}</select></label><label>Evidence<select id="{table_id}-status"><option value="">All records</option><option value="event-reviewed">Officially reviewed events</option><option value="needs-review">Inherited / needs review</option><option value="shortlist">Free + cash evidence</option><option value="saved">Saved only</option></select></label><label>Agent / AI<select id="{table_id}-agent"><option value="">Any policy</option>{''.join(f'<option value="{k}">{e(v)}</option>' for k,v in AGENT.items())}</select></label><button type="button" class="button secondary small" data-reset="{table_id}">Reset</button></div><div class="table-summary"><span data-count="{table_id}" role="status" aria-live="polite">{len(items)} records</span><button type="button" class="text-button" data-export="{table_id}">Export visible CSV ↓</button></div></div>
<div class="table-shell"><table id="{table_id}" class="catalog-table"><caption class="sr-only">Competition evidence table. A dash means the value is not confirmed. Each reviewed event links to its official source and evidence. Inherited rows are not verified offers.</caption><thead><tr>{head}</tr></thead><tbody>{''.join(body)}</tbody></table></div><div class="empty-state" data-empty="{table_id}" hidden><h3>No matching records</h3><p>Try a broader search or reset the filters.</p></div><nav class="pagination" data-pagination="{table_id}" aria-label="Table pages" hidden><button type="button" class="button secondary small" data-prev="{table_id}">← Previous</button><span data-page="{table_id}"></span><button type="button" class="button secondary small" data-next="{table_id}">Next →</button></nav>'''

def category_cards():
    return '<div class="category-grid">'+''.join(f'''<a class="category-card" href="category-{k}.html"><span class="category-icon" aria-hidden="true">{icon}</span><div><h3>{e(name)}</h3><p>{e(desc)}</p></div><span class="category-count">{sum(r['category']==k for r in rows)} <span aria-hidden="true">→</span></span></a>''' for k,name,desc,icon in CATS)+'</div>'

def layout(title, content, active='overview', description='A source-linked dashboard for free-to-enter cash-prize competitions. Confirmed facts, clear limits, and a separate review queue.'):
    nav=[('overview','index.html','Overview','▦'),('shortlist','shortlist.html','Shortlist','✦'),('all','all.html','All competitions','≡'),('saved','saved.html','Saved','☆'),('summary','summary.html','Executive summary','▤'),('flagged','flagged.html','Flagged for review','⚑'),('sources','sources.html','Source notebook','↗'),('methodology','methodology.html','Method & limits','✓')]
    navhtml=''.join(f'<a href="{href}" class="nav-link {"active" if active==key else ""}" {"aria-current=page" if active==key else ""}><span aria-hidden="true">{icon}</span>{e(label)}</a>' for key,href,label,icon in nav)
    cats=''.join(f'<a href="category-{k}.html">{e(v)}</a>' for k,v,_,_ in CATS)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description)}"><meta name="theme-color" content="#12233f"><title>{e(title)} · PrizeLens</title><link rel="stylesheet" href="assets/style.css"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><script src="assets/app.js" defer></script></head><body><a class="skip-link" href="#content">Skip to content</a><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">p<span>•</span></span><span>PrizeLens<small>COMPETITION RESEARCH</small></span></a><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation">{navhtml}</nav><div class="sidebar-note"><span class="status-dot"></span><strong>Evidence before entry</strong><p>No deposits. No affiliate links. No invented prize values.</p></div><a class="repo-link" href="https://github.com/sassnarep3-star/Own2" target="_blank" rel="noopener noreferrer">View repository ↗</a></aside><div class="main-shell"><header class="topbar"><a class="mobile-brand" href="index.html">PrizeLens<span>•</span></a><div class="topbar-context">Research workspace <span>/</span> <strong>{e(title)}</strong></div><span class="audit-pill">Audit · 02 Nov 2026</span></header><nav class="mobile-nav" aria-label="Mobile navigation">{navhtml}</nav><main id="content" tabindex="-1">{content}</main><footer><div><strong>PrizeLens</strong><span>Independent research. Official rules govern.</span></div><div class="footer-links"><a href="methodology.html">Method & limits</a><a href="repo-audit.html">Repository audit</a><a href="data/catalog.csv" download>Download CSV</a><a href="../">Other project views</a></div><details class="footer-categories"><summary>Browse all nine categories</summary><div>{cats}</div></details><p>Static snapshot checked {AUDIT}. “Open” refers to the published window on that date, not a live account or submission test. Prize pools are not expected earnings.</p></footer></div></div></body></html>'''

def page(name,title,content,active,desc=None):
    (ROOT/name).write_text(layout(title,content,active,desc or 'A source-linked dashboard for free-to-enter cash-prize competitions. Confirmed facts, clear limits, and a separate review queue.'))

def heading(kicker,title,subtitle,actions=''):
    return f'<div class="page-heading"><div><div class="eyebrow">{kicker}</div><h1>{title}</h1><p>{subtitle}</p></div>{actions}</div>'

def stat(value,label,note,kind=''):
    return f'<div class="stat {kind}"><span class="stat-value">{value}</span><strong>{label}</strong><small>{note}</small></div>'

# Overview
featured_rows=''.join(f'''<tr><td><a class="featured-name" href="sources.html#{r['id']}">{e(r['name'])}</a><span class="cell-note">{e(r['requirements'])}</span></td><td>{e(money(r['top_cash_usd']))}<span class="cell-note">top published cash award</span></td><td>{e(r['fields']['deadline'])}</td><td><span class="agent-label {r['agent_policy']}">{e(AGENT[r['agent_policy']])}</span></td><td>{ext(r['official_url'],'Official rules')}</td></tr>''' for r in featured)
content=heading('COMPETITION INTELLIGENCE','Find the prize.<br><span>Know the catch.</span>','A calmer way to compare free-entry competitions. Start with official evidence, then check eligibility, effort and agent rules before you invest time.', '<a class="button primary" href="shortlist.html">Explore the shortlist <span aria-hidden="true">→</span></a>')
content+=f'''<section class="stats-grid" aria-label="Audit totals">{stat(counts['inherited'],'Inherited listings','Full source inventory retained')}{stat(counts['events'],'Event-level reviews','Official pages read for this audit','blue')}{stat(counts['shortlist'],'Free + cash evidence','Published windows open or closing','green')}{stat(counts['missing_source'],'No official source','Blank source cells; flagged for review','amber')}</section>
<div class="notice"><span aria-hidden="true">ⓘ</span><p><strong>Research, not a guarantee.</strong> Free entry does not mean free to win. Compute, equipment, taxes and time can cost money. Personal eligibility and payout are not guaranteed.</p></div>
<section class="panel"><div class="section-heading"><div><div class="eyebrow">START HERE</div><h2>A practical research shortlist</h2><p>Six event-level leads with explicit entry and cash evidence. This is not an earnings ranking.</p></div><a class="text-link" href="shortlist.html">View all {len(short)} →</a></div><div class="table-shell"><table class="featured-table"><caption class="sr-only">Six featured competitions with official source links</caption><thead><tr><th scope="col">Competition / work required</th><th scope="col">Top cash award</th><th scope="col">Published deadline</th><th scope="col">Agent / AI</th><th scope="col">Source</th></tr></thead><tbody>{featured_rows}</tbody></table></div></section>
<section class="decision-grid"><article class="decision-card dark"><span class="eyebrow">FOR AN AI CODING WORKFLOW</span><h2>Start with the rules,<br>not the biggest number.</h2><p>Kiroween explicitly requires Kiro. UGREEN limits outside-person development. Codegeist and PayPal mention AI or technical assistance without clearly approving autonomous agent authorship.</p><a href="summary.html#agent-findings" class="button light">Read the decision brief →</a></article><article class="decision-card"><span class="eyebrow">DO NOT SKIP</span><h2>Three checks before entry</h2><ol class="check-list"><li><span>1</span><div><strong>Can you enter?</strong><p>Residency, age, membership and team restrictions.</p></div></li><li><span>2</span><div><strong>Is it really cash?</strong><p>Separate money from credits, gift cards and conditional jackpots.</p></div></li><li><span>3</span><div><strong>Can an agent help?</strong><p>AI-themed does not mean agent-authored entries are allowed.</p></div></li></ol></article></section>
<section><div class="section-heading"><div><div class="eyebrow">BROWSE BY CATEGORY</div><h2>One inventory. Nine clear paths.</h2><p>Category counts include unverified inherited leads, not just recommended competitions.</p></div></div>{category_cards()}</section>
<section class="panel"><div class="section-heading"><div><div class="eyebrow">AUDIT FINDINGS</div><h2>What changed after checking the source</h2></div><a class="text-link" href="flagged.html">Open review queue →</a></div><div class="finding-grid"><article><span class="finding-number">01</span><h3>Broken links are not offers</h3><p>The old Codegeist URL serves 2024 rules. The current event uses a different official subdomain.</p><a href="sources.html#event-codegeist">See the evidence →</a></article><article><span class="finding-number">02</span><h3>“Free” can hide a gate</h3><p>Meta VR Start says no purchase necessary, but requires program membership. Its practical cost is unconfirmed.</p><a href="sources.html#event-meta-start">Review the gate →</a></article><article><span class="finding-number">03</span><h3>Cash-equivalent is not cash</h3><p>FutureEval advertises a prize pool, but the general rules allow cash equivalents at the operator’s discretion.</p><a href="sources.html#event-futureeval">Read the payout rule →</a></article></div></section>'''
page('index.html','Overview',content,'overview')

# Catalog pages
for filename,title,items,active,subtitle in [
 ('all.html','All competitions',rows,'all','Every inherited listing is retained. Blank cells are intentional: an old ledger claim is not current official evidence.'),
 ('shortlist.html','Research shortlist',short,'shortlist','Free-entry and cash evidence with a published open or closing window. Filter by agent policy and read every caveat; this is not a personal-eligibility or expected-value ranking.'),
 ('saved.html','Saved competitions',rows,'saved','Your shortlist stays in this browser. No account, tracking or server-side storage. Save a row from any competition table.')]:
    content=heading('COMPETITION CATALOG',e(title),subtitle,'<a class="button secondary" href="data/catalog.csv" download>Download full CSV ↓</a>')
    if active=='shortlist': content+='<div class="notice"><span aria-hidden="true">⚑</span><p><strong>Eligibility still controls.</strong> ESPN and CBS exclude Singapore residents from prize eligibility and prohibit automated entries. Sony and Wergle require human-origin work. Codex closes on the audit date.</p></div>'
    content+=f'<section class="panel catalog-panel">{table(items,active)}</section>'
    page(filename,title,content,active)
for key,name,desc,icon in CATS:
    items=[r for r in rows if r['category']==key]
    content=heading('CATEGORY VIEW',e(name),e(desc)+f' {len(items)} records in this static audit.', '<a class="button secondary" href="all.html">All competitions →</a>')
    content+=f'<div class="notice"><span aria-hidden="true">ⓘ</span><p>Only cells backed by an official quote are populated. Inherited names and categories are retained for research coverage; they are not verified current offers.</p></div><section class="panel catalog-panel">{table(items,"category-"+key)}</section>'
    page(f'category-{key}.html',name,content,'all')

# Executive summary
content=heading('DECISION BRIEF','Executive summary','What the evidence supports, where time is best spent, and what still needs review. Prepared 2 November 2026.')
content+=f'''<section class="summary-lead"><div><span class="eyebrow">BOTTOM LINE</span><h2>Use a small, rules-first shortlist.<br>Do not chase headline pools.</h2><p>The source ledger contains 206 listings, but its age, mixed payout types and broken links make it unsafe as a ready-to-enter list. This view retains all 206 identities and adds 18 separately sourced event records. Twelve event records have both free-entry and cash evidence with a published open or closing window; only a subset fits an agent-assisted workflow.</p></div><div class="summary-metrics"><span><strong>206</strong> original identities</span><span><strong>18</strong> event reviews</span><span><strong>9</strong> categories</span></div></section>
<section class="panel prose"><h2>Recommended order of research</h2><div class="recommendation-list"><article><span class="rank">01</span><div><h3>Kiroween — clearest named-agent workflow</h3><p>Official rules require Kiro and evaluate specs, hooks and agent workflows. First prize is $30,000; submission closes 4 December 2026 at 2:00 pm Pacific. The trade-off is a public open-source GitHub repository, a public demo and regional/tool restrictions.</p>{ext('https://kiroween.devpost.com/rules','Official rules')}</div></article><article><span class="rank">02</span><div><h3>UGREEN — low initial submission burden, explicit Singapore listing</h3><p>Round 1 needs a concise PDF and initial skill ZIP, not a demo or NAS runtime. The top cash award is $20,000. Only finalists receive hardware access, and the rules bar an outside person from developing the project or submission materials. Do not assume an external agent is permitted.</p>{ext('https://ugreenhackathon.devpost.com/rules','Official rules')}</div></article><article><span class="rank">03</span><div><h3>Codegeist / PayPal / NFL Big Data Bowl — investigate tool permission first</h3><p>These have documented cash awards and no-fee entry clauses, but their AI or technical-assistance language is not blanket coding-agent authorization. Codegeist closes 22 December; PayPal 12 November; NFL Big Data Bowl 6 January. Read ownership, tool-cost and reproducibility rules before building.</p><div class="inline-links">{ext('https://codegeist2026.devpost.com/rules','Codegeist')}{ext('https://paypalaihackathon.devpost.com/rules','PayPal')}{ext('https://www.kaggle.com/competitions/nfl-big-data-bowl-2027/rules','NFL rules')}</div></div></article></div><p class="muted">Ordering is editorial: explicitness of the agent path, submission requirements and runway. It is not a probability model, hourly-return estimate or financial recommendation.</p></section>
<section class="panel prose" id="agent-findings"><h2>Agent-use findings that change the decision</h2><div class="table-shell"><table class="simple-table"><caption class="sr-only">Agent permissions from official rules</caption><thead><tr><th scope="col">Competition</th><th scope="col">What the official rule establishes</th><th scope="col">Source</th></tr></thead><tbody><tr><td>Kiroween</td><td>Kiro IDE/CLI/Web/Crew required; agent workflows are part of the submission.</td><td>{ext('https://kiroween.devpost.com/rules','Rules §4')}</td></tr><tr><td>Codex x TwitchCon</td><td>AI coding assistants explicitly permitted; Codex session ID required. Closes on the audit date.</td><td>{ext('https://twitchcon-codex.devpost.com/rules','Rules §4')}</td></tr><tr><td>FutureEval</td><td>Bot-only event, but cash-equivalent payout is possible; excluded from strict cash shortlist.</td><td>{ext('https://www.metaculus.com/tournament-rules/','Payout rules')}</td></tr><tr><td>ESPN / CBS</td><td>Automated entries or point-accumulation scripts prohibited. No agent submission workflow.</td><td>{ext('https://fantasy.espn.com/games/nfl-pickem-2026/howtoplay','ESPN §5')} · {ext('https://www.cbssports.com/fantasy/football/games/pickem/rules','CBS §4')}</td></tr><tr><td>Sony / Wergle</td><td>Photographic origin / human-written text required. Generated images or poem text are not eligible entries.</td><td>{ext('https://www.worldphoto.org/sony-world-photography-awards/single-image','Sony rule 4')} · {ext('https://winningwriters.com/our-contests/wergle-flomp-humor-poetry-contest-free','Wergle AI policy')}</td></tr></tbody></table></div></section>
<section class="two-column"><article class="panel prose"><h2>What was verified</h2><ul><li>The upstream repository’s current commit and the pinned 206-listing snapshot.</li><li>Every inherited row’s identity, category, unique ID and official-source pointer presence.</li><li>Field-level quotes for 18 event records, with blanks for unsupported values.</li><li>Official source reachability is reported separately when the audit artifact is available; HTTP success never verifies an offer.</li><li>Generated local links, anchors, assets, CSV parity and deterministic builds are tested.</li></ul></article><article class="panel prose"><h2>What was not verified</h2><ul><li>Current operational terms for every inherited listing. Unsupported fields remain blank and flagged.</li><li>Your personal residency, age, tax status, identity or prize eligibility.</li><li>Actual payout receipt, win probability, expected return or typical earnings.</li><li>Every external page’s full legal terms. Only cited passages support published cells.</li><li>Live login, registration or submission-form availability. No contest accounts or entries were created.</li></ul></article></section>
<section class="panel prose"><h2>Repository irregularities</h2><p>The repository already contains multiple parallel dashboards and audit supplements. This session preserves them and publishes an isolated view instead of overwriting shared data. Historical coordination claims and some root summary counts are stale; the current root checker is the source for current counts. The upstream repository has no detected license, and its <code>100_VERIFIED_CONTESTS.md</code> explicitly says it failed verification and must not be used as a source.</p><div class="inline-links"><a class="button secondary" href="repo-audit.html">Read the repository audit →</a><a class="button secondary" href="flagged.html">Flagged for review →</a><a class="button secondary" href="https://github.com/sassnarep3-star/Own2/blob/main/COORDINATION.md" target="_blank" rel="noopener noreferrer">Coordination log ↗</a></div></section>'''
page('summary.html','Executive summary',content,'summary')

# Methodology
content=heading('HOW TO READ THIS SITE','Method & verification limits','A link is a pointer. A quote is evidence. Neither is a guarantee that you can enter or get paid.')
content+='''<section class="panel prose"><h2>Evidence labels</h2><div class="table-shell"><table class="simple-table"><caption class="sr-only">Meaning of evidence labels</caption><thead><tr><th scope="col">Label</th><th scope="col">Meaning</th><th scope="col">What it does not mean</th></tr></thead><tbody><tr><td><span class="badge green">Free + cash evidence</span></td><td>An official no-fee/free-entry statement and a cash award are quoted; the published window includes the audit date or closes that day.</td><td>Personal eligibility, zero practical cost, guaranteed payout or a live submission-form test.</td></tr><tr><td><span class="badge blue">Partial evidence</span></td><td>Some official facts were read, but a key gate, payout form, prerequisite or timing issue remains.</td><td>A complete legal review or a recommendation to enter.</td></tr><tr><td><span class="badge amber">Needs review</span></td><td>An inherited identity/source pointer retained without current official field verification.</td><td>That the old prize, status, eligibility or link is correct.</td></tr><tr><td><span class="blank">—</span></td><td>Not confirmed from an official source in this audit.</td><td>Zero, “none”, “worldwide”, or permission to infer a value.</td></tr></tbody></table></div></section>
<section class="two-column"><article class="panel prose"><h2>Collection process</h2><ol><li>Read the shared coordination board and claim a non-overlapping namespace.</li><li>Pin the upstream repository commit; retain all 206 identities and nine categories.</li><li>Do not copy old operational claims into current fact cells.</li><li>Open organizer or official administrator pages; record exact excerpts, locators and URLs.</li><li>Leave missing or conflicting values blank and publish the issue in the review queue.</li><li>Generate static pages and test row coverage, evidence, links, CSV and browser behavior.</li></ol></article><article class="panel prose"><h2>Ranking policy</h2><p>No fake “winability” score, hourly rate or expected-value estimate. Prize pools are not comparable to individual awards, and entrant counts are usually unknown.</p><p>The featured order is an editorial research sequence based on explicit agent rules, stated submission requirements and runway. Filters let you choose by category, evidence and agent policy. Top cash award and total pool are kept separate.</p><p>Country names are reproduced only when the official rule lists them. “Worldwide” is never inferred from a working website.</p></article></section>
<section class="panel prose"><h2>Time, money and automation</h2><p>Free entry means the cited rule does not require an entry purchase or fee. It does not eliminate internet, compute, hardware, travel, tax or withdrawal costs. A membership gate with unknown cost is not treated as a confirmed zero-cost opportunity.</p><p>AI assistance is evaluated separately from automated entry. A contest can require an AI product while prohibiting an outside agent from authoring or submitting the entry. Where permission is unclear, the site says so. No automated contest entry, deposit, account creation or prize claim was performed.</p></section>
<section class="panel prose"><h2>Source coverage and freshness</h2><p>The static audit date is 2 November 2026. “Published window open” is a date comparison against the cited rule, not a live check of the entry form. Event pages and rules can change without notice. The source notebook identifies the passages read; unread chunks are not evidence.</p><p>External reachability results, when present, are a separate network observation. A 403, timeout or TLS failure is inconclusive; a 200 response can still be a stale, wrong or non-cash offer. All such limitations are non-blocking review items, not hidden assumptions.</p><div class="inline-links"><a class="button secondary" href="sources.html">Source notebook →</a><a class="button secondary" href="flagged.html">Review queue →</a><a class="button secondary" href="data/catalog.json">Download JSON ↓</a></div></section>'''
page('methodology.html','Method & limits',content,'methodology')

# Source notebook
notebook=[]
for r in rows:
    if r['kind']!='event': continue
    quotes=''.join(f'''<div class="quote-item"><div class="quote-field">{e(ev['field'].replace('_',' ').title())}</div><blockquote>{e(ev['quote'])}</blockquote><div class="quote-meta"><span>{e(ev['locator'])} · checked {e(ev['checked'])}</span>{ext(ev['url'],'Official source')}</div></div>''' for ev in r['evidence'])
    flags=''.join(f'<li>{e(f)}</li>' for f in r['flags'])
    notebook.append(f'''<article class="source-record" id="{e(r['id'])}"><div class="section-heading"><div><span class="eyebrow">{e(r['category_name'])} · {e(r.get('source_name','Official source'))}</span><h2>{e(r['name'])}</h2></div>{badge(r)}</div><div class="source-facts"><div><strong>Eligibility</strong><p>{blank(r['fields'].get('eligibility'))}</p></div><div><strong>Submission requirements</strong><p>{blank(r['fields'].get('requirements'))}</p></div><div><strong>Payout</strong><p>{blank(r['fields'].get('payout'))}</p></div></div>{quotes}<div class="review-note"><strong>Review notes</strong><ul>{flags}</ul></div><a class="text-link" href="all.html#{e(r['id'])}">Back to catalog row →</a></article>''')
content=heading('OFFICIAL EVIDENCE','Source notebook','Exact excerpts supporting the event-level cells. Inherited listings without a current official review remain in the catalog and review queue.')
